using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Lodira.Application.Contributions;
using Lodira.Application.Portfolio;
using Lodira.Application.Abstractions;
using Lodira.Application.Intelligence;
using Lodira.Domain.Entities;
using Lodira.Domain.Enums;
using Lodira.Infrastructure.Persistence;
using Lodira.Api.Services;
namespace Lodira.Api.Controllers;
[ApiController][Route("api/portfolios/{portfolioId:guid}")]
public sealed class ContributionGuidanceController : ControllerBase
{
    private readonly LodiraDbContext db; private readonly PortfolioAssessmentCurrentService current;
    public ContributionGuidanceController(LodiraDbContext db,PortfolioAssessmentCurrentService? current=null){this.db=db;this.current=current??new PortfolioAssessmentCurrentService(db,new PortfolioImpactAssessmentService(),new PortfolioAssessmentFreshnessEvaluator(),Microsoft.Extensions.Logging.Abstractions.NullLogger<PortfolioAssessmentCurrentService>.Instance);}
    [HttpGet("target-allocations")]
    public async Task<ActionResult<IReadOnlyList<TargetAllocationResponse>>> GetTargets(Guid portfolioId,CancellationToken ct){if(!await db.Portfolios.AnyAsync(x=>x.Id==portfolioId,ct))return NotFound();return Ok(await db.TargetAllocations.AsNoTracking().Where(x=>x.PortfolioId==portfolioId).OrderBy(x=>x.AssetClass).Select(x=>new TargetAllocationResponse(x.AssetClass,x.TargetPercentage)).ToListAsync(ct));}
    [HttpPut("target-allocations")]
    public async Task<ActionResult<IReadOnlyList<TargetAllocationResponse>>> PutTargets(Guid portfolioId,TargetAllocationRequest request,CancellationToken ct){if(!await db.Portfolios.AnyAsync(x=>x.Id==portfolioId,ct))return NotFound();if(request.Allocations is null||request.Allocations.Count==0||request.Allocations.Any(x=>!Enum.IsDefined(x.AssetClass)||x.TargetPercentage<0||x.TargetPercentage>100)||request.Allocations.GroupBy(x=>x.AssetClass).Any(x=>x.Count()>1)||Math.Abs(request.Allocations.Sum(x=>x.TargetPercentage)-100m)>.01m)return BadRequest("Defina classes válidas cuja soma seja 100%.");var old=await db.TargetAllocations.Where(x=>x.PortfolioId==portfolioId).ToListAsync(ct);db.TargetAllocations.RemoveRange(old);db.TargetAllocations.AddRange(request.Allocations.Select(x=>new TargetAllocation(portfolioId,x.AssetClass,x.TargetPercentage)));await db.SaveChangesAsync(ct);return Ok(request.Allocations.OrderBy(x=>x.AssetClass).Select(x=>new TargetAllocationResponse(x.AssetClass,x.TargetPercentage)).ToList());}
    [HttpPost("contribution-guidance")]
    public async Task<ActionResult<ContributionGuidance>> Simulate(Guid portfolioId,ContributionRequest request,CancellationToken ct){if(request.Amount<=0)return BadRequest("O valor do aporte deve ser positivo.");var portfolio=await db.Portfolios.Include(x=>x.Positions).ThenInclude(x=>x.Asset).SingleOrDefaultAsync(x=>x.Id==portfolioId,ct);if(portfolio is null)return NotFound();var targets=await db.TargetAllocations.AsNoTracking().Where(x=>x.PortfolioId==portfolioId).ToListAsync(ct);if(targets.Count==0)return Conflict(new{status=ContributionGuidanceStatus.NotConfigured.ToString(),message="Defina as alocações-alvo antes de simular um aporte."});if(portfolio.Positions.Any(x=>!x.CurrentValue.HasValue))return BadRequest("Não há preço válido para todas as posições existentes.");var health=new PortfolioHealthCalculator().Calculate(portfolio,targets);var total=portfolio.Positions.Sum(x=>x.CurrentValue??0);var positions=portfolio.Positions.Where(x=>x.Asset is not null&&x.CurrentValue.HasValue).Select(x=>new GuidancePosition(x.AssetId,x.Asset!.Ticker,x.Asset.AssetClass,x.CurrentValue!.Value,total==0?0:x.CurrentValue.Value/total*100m)).ToList();var ids=positions.Select(x=>x.AssetId).ToHashSet();var assessments=await db.PortfolioAssessments.AsNoTracking().Include(x=>x.InvestmentEvent!).ThenInclude(x=>x.AffectedAssets).Include(x=>x.InvestmentEvent!).ThenInclude(x=>x.Evidence).Where(x=>x.PortfolioId==portfolioId&&x.Status!=AssessmentStatus.Closed&&x.InvestmentEvent!.AffectedAssets.Any(a=>ids.Contains(a.Id))).ToListAsync(ct);assessments=(await current.EnsureFreshAsync(portfolio,targets,assessments,ct)).ToList();var inputs=assessments.Where(x=>x.InvestmentEvent is not null).SelectMany(x=>x.InvestmentEvent!.AffectedAssets.Where(a=>ids.Contains(a.Id)).Select(a=>new GuidanceAssessment(a.Id,x.CapitalDecisionImpact,x.Status,x.InvestmentEvent.Evidence.FirstOrDefault()?.Reference,x.AssessmentVersion))).ToList();return Ok(new ContributionGuidanceCalculator().Calculate(new ContributionGuidanceInput(portfolioId,request.Amount,health,positions,inputs)));}
}
public sealed record TargetAllocationRequest(IReadOnlyList<TargetAllocationItem> Allocations);public sealed record TargetAllocationItem(AssetClass AssetClass,decimal TargetPercentage);public sealed record TargetAllocationResponse(AssetClass AssetClass,decimal TargetPercentage);public sealed record ContributionRequest(decimal Amount);
